		["{item:3173}: Elder Black Bears"] = "{item:3173}：老黑熊掉落",
		["{item:3174}: Forest Lurkers"] = "{item:3174}：森林潜伏者掉落",
		["{item:5026} and the {item:6652}"] = "{item:5026}和{item:6652}",
